system_prompt.output_format:
Debes responder estrictamente en formato JSON válido con la siguiente estructura:
{
    "segmentos": [
        {
            "nombre": "Nombre oficial de la línea de negocio (ej. Homebuilding, iPhone, Intelligent Cloud)",
            "descripcion": "Descripción detallada de qué productos, servicios o marcas comprende esta línea.",
            "porcentaje_ultimo_ano": 52.1,
            "crecimiento_yoy_pct": 5.4,
            "color_sugerido": "#3B82F6"
        }
    ],
    "años": ["2021", "2022", "2023", "2024", "2025"],
    "historico_segmentos": {
        "Nombre Línea 1": [120.5, 135.0, 150.2, 162.8, 175.4],
        "Nombre Línea 2": [0.0, 0.0, 15.2, 28.4, 45.1]
    },
    "unidad_monetaria": "Billion USD | Million USD",
    "analisis_diversificacion": "Evaluación de 3-4 líneas sobre la diversificación del flujo de ingresos, dependencias operativas y motor de mayor crecimiento."
}
